import{_ as e,C as r,o as h,c as n,j as d,a as l,E as i,ah as o}from"./chunks/framework.DuX8SFU5.js";const u=JSON.parse('{"title":"AM_CAN_BRIDGE — даташит","description":"","frontmatter":{"title":"AM_CAN_BRIDGE — даташит","pdf":"/pdf/AM_CAN_BRIDGE_datasheet.pdf","pdfStyle":"datasheet","pageClass":"datasheet-page","preliminary":true},"headers":[],"relativePath":"am_can_to_can_bridge/datasheet.md","filePath":"am_can_to_can_bridge/datasheet.md"}'),s={name:"am_can_to_can_bridge/datasheet.md"};function C(b,t,A,N,_,c){const a=r("AssetImage");return h(),n("div",null,[t[0]||(t[0]=d("h2",{id:"_1-описание",tabindex:"-1"},[l("1. Описание "),d("a",{class:"header-anchor",href:"#_1-описание","aria-label":'Permalink to "1. Описание"'},"​")],-1)),t[1]||(t[1]=d("p",null,"AM_CAN_BRIDGE — шлюз, который включается в разрыв штатной CAN-линии машины и делит её на два сегмента, CAN0 IN и CAN0 OUT. Кадры между сегментами пересылает прошивка: она может передавать их без изменений, фильтровать, заменять выбранные значения или формировать сообщения от имени штатного узла. Бортовой компьютер подключается по Ethernet или по независимой шине CAN2.",-1)),i(a,{name:"am_can_bridge_board.webp",alt:"AM_CAN_BRIDGE, вид платы"}),t[2]||(t[2]=o(`<p>Аппаратного обхода между CAN0 IN и CAN0 OUT нет: без работающей прошивки кадры между сегментами не передаются. Характеристики, помеченные «уточняется», не подтверждены измерениями или финальной документацией платы.</p><h2 id="_2-возможности" tabindex="-1">2. Возможности <a class="header-anchor" href="#_2-возможности" aria-label="Permalink to &quot;2. Возможности&quot;">​</a></h2><ul><li>CAN0 IN: контроллер CAN FD TCAN4550-Q1, связь с MCU по SPI; вход отключается двумя последовательными релейными каскадами.</li><li>CAN0 OUT: FDCAN1 MCU и трансивер TJA1042, дублирован на разъёме CAN1_C.</li><li>CAN2: FDCAN2 MCU и трансивер TJA1042, выведен на M8, M12 и CAN2_C.</li><li>Ethernet 10/100BASE-TX: PHY LAN8742A по RMII, разъём M8.</li><li>USB-C, USB 2.0 Full Speed: сервисное подключение и резервное питание системной шины 5 В.</li><li>Питание 24 В через XT30, M8 или M12; DC/DC-модуль 5 В; диодное объединение с питанием от USB.</li><li>Измерение входного напряжения, контроль наличия основного и USB-питания.</li><li>Выход на вибромотор (драйвер DRV2603).</li></ul><h2 id="_3-характеристики" tabindex="-1">3. Характеристики <a class="header-anchor" href="#_3-характеристики" aria-label="Permalink to &quot;3. Характеристики&quot;">​</a></h2><h3 id="_3-1-электрические" tabindex="-1">3.1. Электрические <a class="header-anchor" href="#_3-1-электрические" aria-label="Permalink to &quot;3.1. Электрические&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Мин.</th><th>Тип.</th><th>Макс.</th><th>Ед.</th><th>Примечание</th></tr></thead><tbody><tr><td>Напряжение питания Vin, текущая ревизия</td><td>18</td><td>24</td><td>24</td><td>В</td><td>До валидации платы</td></tr><tr><td>Напряжение питания Vin, рекомендуемый верхний предел</td><td>—</td><td>—</td><td>30</td><td>В</td><td>По рекомендованному VSUP TCAN4550-Q1</td></tr><tr><td>Сервисное питание USB VBUS</td><td>—</td><td>5</td><td>—</td><td>В</td><td></td></tr><tr><td>Скорость CAN</td><td>—</td><td>—</td><td>1</td><td>Мбит/с</td><td>Классический CAN; CAN FD сквозь мост не заявлен</td></tr><tr><td>Ethernet</td><td>—</td><td>—</td><td>100</td><td>Мбит/с</td><td>10/100BASE-TX</td></tr><tr><td>Выходная мощность шины 5 В</td><td>—</td><td>—</td><td>уточняется</td><td>Вт</td><td>Требуется тепловой расчёт</td></tr></tbody></table><h3 id="_3-2-предельно-допустимые-параметры" tabindex="-1">3.2. Предельно допустимые параметры <a class="header-anchor" href="#_3-2-предельно-допустимые-параметры" aria-label="Permalink to &quot;3.2. Предельно допустимые параметры&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Предел</th><th>Основание</th></tr></thead><tbody><tr><td>Vin, положительное</td><td>42 В</td><td>Абсолютный максимум VSUP TCAN4550-Q1; рабочий предел ниже</td></tr><tr><td>Vin, отрицательное</td><td>не допускается</td><td>Защиты от переполюсовки на плате нет</td></tr><tr><td>CANH, CANL на CAN0 IN</td><td>±58 В</td><td>Предел выводов TCAN4550-Q1, а не разъёма или платы</td></tr></tbody></table><h3 id="_3-3-механические" tabindex="-1">3.3. Механические <a class="header-anchor" href="#_3-3-механические" aria-label="Permalink to &quot;3.3. Механические&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение</th></tr></thead><tbody><tr><td>Размер платы</td><td>72,1 × 77,1 мм</td></tr><tr><td>Толщина платы</td><td>1,6 мм</td></tr><tr><td>Крепёжные отверстия</td><td>4, сетка центров 64,8 × 69,8 мм</td></tr><tr><td>Диаметр отверстий, высота сборки, масса</td><td>уточняются</td></tr></tbody></table><h3 id="_3-4-условия-эксплуатации" tabindex="-1">3.4. Условия эксплуатации <a class="header-anchor" href="#_3-4-условия-эксплуатации" aria-label="Permalink to &quot;3.4. Условия эксплуатации&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение</th></tr></thead><tbody><tr><td>Рабочая температура</td><td>уточняется: плата не квалифицирована</td></tr><tr><td>Степень защиты</td><td>обеспечивается корпусом</td></tr></tbody></table><h2 id="_4-функциональная-схема" tabindex="-1">4. Функциональная схема <a class="header-anchor" href="#_4-функциональная-схема" aria-label="Permalink to &quot;4. Функциональная схема&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vin: XT30 / M8 / M12 ──► DC/DC 5 В ──┐</span></span>
<span class="line"><span>USB-C 5 В ───────────────────────────┴─► диодное ИЛИ ──► системная шина 5 В ──► MCU</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CAN0 IN ──► реле 1 ──► реле 2 ──► TCAN4550 ──SPI──► MCU ──FDCAN1──► TJA1042 ──► CAN0 OUT, CAN1_C</span></span>
<span class="line"><span>                                                    MCU ──FDCAN2──► TJA1042 ──► CAN2: M8, M12, CAN2_C</span></span>
<span class="line"><span>                                                    MCU ──RMII────► LAN8742A ──► Ethernet: M8</span></span></code></pre></div><h2 id="_5-разъемы-и-распиновка" tabindex="-1">5. Разъёмы и распиновка <a class="header-anchor" href="#_5-разъемы-и-распиновка" aria-label="Permalink to &quot;5. Разъёмы и распиновка&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Разъём</th><th>Тип</th><th>Назначение</th></tr></thead><tbody><tr><td>XT30</td><td>2 конт.</td><td>Основное питание Vin, GND</td></tr><tr><td>CAN0</td><td>6 конт.</td><td>Разрываемая линия CAN0: вход и выход</td></tr><tr><td>M8</td><td>8 конт.</td><td>Ethernet, CAN2, питание</td></tr><tr><td>M12</td><td>5 конт.</td><td>CAN2, питание</td></tr><tr><td>CAN1_C</td><td>JST-GH, 4 конт.</td><td>Параллельный доступ к CAN0 OUT</td></tr><tr><td>CAN2_C</td><td>JST-GH, 4 конт.</td><td>Параллельный доступ к CAN2</td></tr><tr><td>USB-C</td><td>USB-C</td><td>USB 2.0 FS, сервисное питание</td></tr><tr><td>MOTOR</td><td>3 конт.</td><td>Вибромотор</td></tr></tbody></table><h3 id="can0" tabindex="-1">CAN0 <a class="header-anchor" href="#can0" aria-label="Permalink to &quot;CAN0&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th><th>Описание</th></tr></thead><tbody><tr><td>1</td><td>—</td><td>Не подключён</td></tr><tr><td>2</td><td>CAN0_H_OUT</td><td>Выход CAN0 после программного моста</td></tr><tr><td>3</td><td>CAN0_L_OUT</td><td>Выход CAN0 после программного моста</td></tr><tr><td>4</td><td>GND</td><td>Сигнальная земля</td></tr><tr><td>5</td><td>CAN0_L_IN</td><td>Вход CAN0 до релейных каскадов</td></tr><tr><td>6</td><td>CAN0_H_IN</td><td>Вход CAN0 до релейных каскадов</td></tr></tbody></table><h3 id="m8" tabindex="-1">M8 <a class="header-anchor" href="#m8" aria-label="Permalink to &quot;M8&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th><th>Описание</th></tr></thead><tbody><tr><td>1</td><td>GND</td><td>Земля; корпус разъёма также на GND</td></tr><tr><td>2</td><td>ETH A−</td><td>Ethernet, пара A</td></tr><tr><td>3</td><td>ETH A+</td><td>Ethernet, пара A</td></tr><tr><td>4</td><td>ETH B−</td><td>Ethernet, пара B</td></tr><tr><td>5</td><td>ETH B+</td><td>Ethernet, пара B</td></tr><tr><td>6</td><td>Vin</td><td>Основное питание, объединено с XT30 и M12</td></tr><tr><td>7</td><td>CAN2_H</td><td>CAN2, без встроенной терминации</td></tr><tr><td>8</td><td>CAN2_L</td><td>CAN2, без встроенной терминации</td></tr></tbody></table><h3 id="m12" tabindex="-1">M12 <a class="header-anchor" href="#m12" aria-label="Permalink to &quot;M12&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>CAN2_L</td></tr><tr><td>2</td><td>CAN2_H</td></tr><tr><td>3</td><td>GND</td></tr><tr><td>4</td><td>Vin</td></tr><tr><td>5</td><td>GND</td></tr></tbody></table><h3 id="can1-c-can2-c" tabindex="-1">CAN1_C, CAN2_C <a class="header-anchor" href="#can1-c-can2-c" aria-label="Permalink to &quot;CAN1_C, CAN2_C&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Конт.</th><th>CAN1_C</th><th>CAN2_C</th></tr></thead><tbody><tr><td>1</td><td>—</td><td>—</td></tr><tr><td>2</td><td>CAN1_H (= CAN0_H_OUT)</td><td>CAN2_H</td></tr><tr><td>3</td><td>CAN1_L (= CAN0_L_OUT)</td><td>CAN2_L</td></tr><tr><td>4</td><td>—</td><td>—</td></tr></tbody></table><h2 id="_6-описание-функции" tabindex="-1">6. Описание функций <a class="header-anchor" href="#_6-описание-функции" aria-label="Permalink to &quot;6. Описание функций&quot;">​</a></h2><h3 id="_6-1-мост-can0-и-отключение-входа" tabindex="-1">6.1. Мост CAN0 и отключение входа <a class="header-anchor" href="#_6-1-мост-can0-и-отключение-входа" aria-label="Permalink to &quot;6.1. Мост CAN0 и отключение входа&quot;">​</a></h3><p>CAN0 IN и CAN0 OUT — разные сегменты без электрического соединения в штатной работе. Кадр со входа принимает TCAN4550, и прошивка решает, пересылать ли его на выход через FDCAN1. Релейные каскады разрывают только путь от CAN0 IN к TCAN4550 и не затрагивают CAN0 OUT.</p><table tabindex="0"><thead><tr><th>Реле 1</th><th>Реле 2</th><th>Путь CAN0 IN → TCAN4550</th><th>Когда</th></tr></thead><tbody><tr><td>выкл</td><td>выкл</td><td>замкнут</td><td>при старте и без питания</td></tr><tr><td>вкл</td><td>выкл</td><td>разомкнут каскадом 1</td><td>по команде прошивки</td></tr><tr><td>выкл</td><td>вкл</td><td>разомкнут каскадом 2</td><td>по команде прошивки</td></tr><tr><td>вкл</td><td>вкл</td><td>разомкнут обоими каскадами</td><td>по команде прошивки, с резервированием</td></tr></tbody></table><p>Обратной связи о фактическом состоянии контактов нет.</p><h3 id="_6-2-питание" tabindex="-1">6.2. Питание <a class="header-anchor" href="#_6-2-питание" aria-label="Permalink to &quot;6.2. Питание&quot;">​</a></h3><p>Входы XT30, M8 и M12 соединены параллельно и образуют одну шину Vin. DC/DC-модуль формирует 5 В от Vin; питание от USB объединено с ним диодами Шоттки, обратный ток между источниками исключён. Входное напряжение измеряется через делитель Vin / 19; наличие основного и USB-питания сообщается MCU отдельными сигналами.</p><h3 id="_6-3-режимы-прошивки" tabindex="-1">6.3. Режимы прошивки <a class="header-anchor" href="#_6-3-режимы-прошивки" aria-label="Permalink to &quot;6.3. Режимы прошивки&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Режим</th><th>Действие</th></tr></thead><tbody><tr><td>Пересылка</td><td>Разрешённые кадры передаются без изменения данных</td></tr><tr><td>Фильтрация</td><td>Кадры передаются или блокируются по правилам: список разрешённых идентификаторов, диапазоны, частота, счётчики</td></tr><tr><td>Замена</td><td>Выбранный кадр блокируется, вместо него передаётся кадр с новым значением</td></tr><tr><td>Формирование</td><td>Шлюз формирует сообщения отсутствующего или отключённого штатного узла</td></tr></tbody></table><p>Программная фильтрация не является функцией безопасности без отдельного анализа отказов.</p><h2 id="_7-рекомендации-по-применению" tabindex="-1">7. Рекомендации по применению <a class="header-anchor" href="#_7-рекомендации-по-применению" aria-label="Permalink to &quot;7. Рекомендации по применению&quot;">​</a></h2><p><strong>Монтаж.</strong> Четыре стойки по сетке 64,8 × 69,8 мм; усилие кабелей M8, M12 и XT30 передаётся на корпус, а не на пайку разъёмов. Для вибрационной среды предусматриваются фиксация модулей и реле, покрытие платы и испытание сборки.</p><p><strong>Питание.</strong> Стабилизированный источник 24 В с предохранителем или ограничением тока, внешняя защита от переполюсовки и импульсов. Питание не подаётся одновременно через XT30, M8 и M12 от разных источников: эти контакты соединены напрямую.</p><p><strong>CAN.</strong> Витая пара; две терминальные нагрузки 120 Ом только на физических концах каждого сегмента, на плате терминаторов нет.</p><h2 id="_8-известные-ограничения" tabindex="-1">8. Известные ограничения <a class="header-anchor" href="#_8-известные-ограничения" aria-label="Permalink to &quot;8. Известные ограничения&quot;">​</a></h2><ul><li>Маркировка пары B Ethernet на механическом чертеже разъёма M8 расходится со схемой; распиновка выше дана по схеме.</li><li>Защиты от переполюсовки по Vin на плате нет.</li><li>Гальванической изоляции CAN нет.</li><li>Отдельной ESD-защиты линий USB D+/D− нет.</li><li>Один аналоговый вход MCU по схеме подключён к 5 В и требует исправления в следующей ревизии.</li></ul><h2 id="_9-история-документа" tabindex="-1">9. История документа <a class="header-anchor" href="#_9-история-документа" aria-label="Permalink to &quot;9. История документа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Версия</th><th>Дата</th><th>Изменения</th></tr></thead><tbody><tr><td>0.1</td><td>2026-10-01</td><td>Первая редакция даташита</td></tr></tbody></table>`,42))])}const T=e(s,[["render",C]]);export{u as __pageData,T as default};
